import React,{useState} from 'react';import{createRoot}from'react-dom/client';
function App(){const[state,set]=useState({name:'',email:'',intro:''});(window as any).EvalState=()=>state;const b=new URLSearchParams(location.search).get('layout')==='B';return <section aria-label="个人资料"><h1>个人资料</h1>{(b?['intro','email','name']:['name','email','intro']).map(key=><label style={{display:'block',margin:16}} key={key}>{({name:b?'真实姓名':'姓名',email:b?'电子邮箱':'邮箱',intro:b?'自我介绍':'个人简介'})[key]}{key==='intro'?<textarea value={state.intro} onChange={e=>set({...state,intro:e.target.value})}/>:<input value={state[key as 'name'|'email']} onChange={e=>set({...state,[key]:e.target.value})}/>}</label>)}</section>};createRoot(document.getElementById('root')!).render(<App/>);
